using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptionSourceCorruptionLinkEffect", menuName = "Data/Battle/Effects/Enemy/CorruptionSourceCorruptionLink Effect")]
public class CorruptionSourceCorruptionLinkEffect : Effect
{
	private const string corruptedLinkEffectStayActiveID = "CorruptedLinkEffectStayActive";

	[Header("Possible Effects")]
	[SerializeField]
	private Effect effect;

	[SerializeField]
	private bool hiddenLink;

	[SerializeField]
	private CorruptionLinkEffect corruptionLinkEffect;

	public Effect Effect => effect;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string arg = "Corrupted Sentinel";
		if (effectOwner != null)
		{
			if (GameScenesUtils.IsBattleScene() && (bool)effectOwner.GetComponent<CorruptedAnimalInitializer>())
			{
				arg = ((!(effectOwner.GetComponent<CorruptedAnimalInitializer>().CorruptedAnimalData.CorruptedAnimalName == "CorruptedHevelius")) ? base.localizationManager.GetLocalizedString(corruptionLinkEffect.CorruptedSentinelID) : base.localizationManager.GetLocalizedString(corruptionLinkEffect.CorruptedAssistantID));
			}
		}
		else
		{
			arg = base.localizationManager.GetLocalizedString("CorruptedSentinel");
		}
		string text = Smart.Format(base.localizationManager.GetLocalizedString("CorruptedLinkEffectStayActive"), arg);
		return effect.GetEffectDescription(hiddenLink ? EffectsValues.INFINITY : amount) + "\n" + text;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effect.ActivateEffect(effectAmount, effectOwner);
		return effectAmount;
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effect.ActivateEffectWithSource(effectAmount, effectOwner, source);
		return effectAmount;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		effect.RemoveEffect(effectAmount, effectOwner);
	}
}
